def test_engine_does_not_peek():
    bars = make_bars(400)
    for cut in (100, 200, 300):          # cuts in the middle, not at the ends
        assert lookahead_check(engine, bars, cut)


def test_engine_with_costs_does_not_peek():
    bars = make_bars(400)
    for cut in (100, 200, 300):
        assert lookahead_check(engine_with_costs, bars, cut)

