import contextlib as _zc, inspect as _zi, io as _zio, sys as _zs
import pytest as _zpt


def _zq_pytest(swap=None, collect=False, show=False):
    # write the learner's code to test_mine.py and run real pytest on it, with any functions swapped in
    open("test_mine.py", "w").write(__learner_source__)
    _zs.modules.pop("test_mine", None)
    seen = []

    class _Swap:
        def pytest_collection_modifyitems(self, items):
            seen.extend(items)
            for m in {id(i.module): i.module for i in items}.values():
                for k, v in (swap or {}).items():
                    setattr(m, k, v)

    args = ["-q", "-p", "no:cacheprovider", "test_mine.py"] + (["--collect-only"] if collect else [])
    if show:
        code = _zpt.main(args, plugins=[_Swap()])
    else:
        with _zc.redirect_stdout(_zio.StringIO()), _zc.redirect_stderr(_zio.StringIO()):
            code = _zpt.main(args, plugins=[_Swap()])
    return int(code), seen


def run_tests():
    return _zq_pytest(show=True)[0]


def outcome(**swap):
    code = _zq_pytest(swap)[0]
    return {0: "passed", 1: "failed", 5: "no tests"}.get(code, "error")


def count(test=None, fixture=None):
    items = _zq_pytest(collect=True)[1]
    return sum(1 for i in items if test in (None, getattr(i, "originalname", i.name))
               and (fixture is None or fixture in _zi.signature(i.function).parameters))


def is_fixture(f):
    return hasattr(f, "_pytestfixturefunction") or type(f).__name__ == "FixtureFunctionDefinition"
